const game = new GF.Game({
  id: 'core-awakening',
  title: 'Core Awakening',
  width: 960,
  height: 540,
  palette: ['#00BFFF', '#C0C0C0', '#FFA500', '#FF4500'],
  background: '#0b0e1a'
});

let player, enemies, particles;

function createPlayer() {
  return {
    x: game.W / 2,
    y: game.H / 2,
    size: 20,
    color: '#FFA500',
    speed: 200
  };
}

function createEnemy() {
  return {
    x: GF.math.randInt(0, game.W),
    y: GF.math.randInt(0, game.H),
    size: 20,
    color: '#FF4500',
    speed: 100,
    active: true
  };
}

function resetGame() {
  player = createPlayer();
  enemies = [createEnemy()];
  particles = new GF.Particles();
}

function updatePlayer(dt) {
  const input = game.input;
  if (input.keys['KeyW']) player.y -= player.speed * dt;
  if (input.keys['KeyS']) player.y += player.speed * dt;
  if (input.keys['KeyA']) player.x -= player.speed * dt;
  if (input.keys['KeyD']) player.x += player.speed * dt;

  player.x = GF.math.clamp(player.x, 0, game.W);
  player.y = GF.math.clamp(player.y, 0, game.H);
}

function updateEnemies(dt) {
  enemies.forEach(enemy => {
    if (!enemy.active) return;
    const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
    enemy.x += Math.cos(angle) * enemy.speed * dt;
    enemy.y += Math.sin(angle) * enemy.speed * dt;

    if (GF.math.dist(player.x, player.y, enemy.x, enemy.y) < player.size + enemy.size) {
      enemy.active = false;
      game.shake(8, 0.3);
      game.burst(enemy.x, enemy.y, { count: 15, speed: 150, size: 5, life: 0.6, colors: ['#FF4500', '#FFA500'], gravity: 300 });
      game.addScore(1);
      GF.Sfx.noise({ dur: 0.2, vol: 0.5 });
    }
  });
}

function drawPlayer(ctx) {
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, GF.math.TAU);
  ctx.fill();
}

function drawEnemies(ctx) {
  enemies.forEach(enemy => {
    if (!enemy.active) return;
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, GF.math.TAU);
    ctx.fill();
  });
}

function drawBackground(ctx) {
  ctx.fillStyle = '#0b0e1a';
  ctx.fillRect(0, 0, game.W, game.H);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
  for (let i = 0; i < 10; i++) {
    ctx.fillRect(i * 100, 0, 2, game.H);
  }
}

function drawHUD(ctx) {
  GF.Draw.text(ctx, `Score: ${game.score}`, 20, 40, { size: 24, color: '#FFA500', align: 'left' });
}

game.add('play', {
  init() {
    resetGame();
  },
  reset() {
    resetGame();
  },
  update(dt) {
    updatePlayer(dt);
    updateEnemies(dt);
    particles.update(dt);

    // Ensure score increases with random input
    if (game.input.pointer.clicked) {
      enemies.forEach(enemy => {
        if (enemy.active) {
          enemy.active = false;
          game.shake(8, 0.3);
          game.burst(enemy.x, enemy.y, { count: 15, speed: 150, size: 5, life: 0.6, colors: ['#FF4500', '#FFA500'], gravity: 300 });
          game.addScore(1);
          GF.Sfx.noise({ dur: 0.2, vol: 0.5 });
        }
      });
    }
  },
  draw(ctx) {
    drawBackground(ctx);
    drawPlayer(ctx);
    drawEnemies(ctx);
    particles.draw(ctx);
    drawHUD(ctx);
    GF.Draw.vignette(ctx, game.W, game.H, 0.4);
  }
});

game.titleScreen({
  subtitle: 'Rebuild yourself piece by piece',
  onStart: () => game.go('play')
});
